import httpx, json

results = {}
for label, base in [('backend-direct', 'http://127.0.0.1:18742'), ('frontend-proxy', 'http://127.0.0.1:18743')]:
    for path in ['/api/health', '/api/models']:
        r = httpx.get(base + path, timeout=10)
        results[f'{label} {path}'] = {'status': r.status_code, 'body': r.text[:300]}

for k, v in results.items():
    print(f'--- {k} ---')
    print(f'  HTTP {v["status"]}')
    print(f'  {v["body"][:200]}')
